 || 'bWl0dGVkIHdvcmsuClNvdXJjZSBXUklURSBhbmQgYXBwIG93bmVyc2hpcCBhcmUgY29kZS1kZXBsb3ltZW50IHByaXZpbGVnZXMuIERvIG5vdCBncmFudApB'
 || 'Q0NPVU5UQURNSU4gdG8gd29ya3Nob3AgYXR0ZW5kZWVzIG9yIGJyb2FkZW4gYWNjZXNzIHRvIHNvdXJjZSBkYXRhLgoKU3RvcCBvbiBhIG1pc3NpbmcgYnVp'
 || 'bGQgY2FwYWJpbGl0eSBvciBwcml2aWxlZ2UgYW5kIHJlcG9ydCB0aGUgZXhhY3QgYmxvY2tlci4KRG8gbm90IGNsYWltIGEgZml4dHVyZSBwcm92ZXMgYSBy'
 || 'ZWFsIGN1c3RvbWVyIGJhY2tlbmQuIE5ldmVyIGV4cG9ydCBhY2NvdW50CmRhdGEgb3Igc291cmNlIGNvZGUgdG8gYW4gZXh0ZXJuYWwgc2VydmljZS4K')) || ''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE');
  stmts := ARRAY_APPEND(:stmts,
    'COPY INTO @' || :tgt || '.APP_STAGE/source/50ccc28b0e3ca4f5/assets/app.js FROM (SELECT BASE64_DECODE_STRING(''' || BASE64_ENCODE(BASE64_DECODE_STRING('KGZ1bmN0aW9uKCl7InVzZSBzdHJpY3QiO2Z1bmN0aW9uIHVjKGEpe3JldHVybiBhJiZhLl9fZXNNb2R1bGUmJk9iamVjdC5wcm90b3R5cGUuaGFzT3duUHJv'
 || 'cGVydHkuY2FsbChhLCJkZWZhdWx0Iik/YS5kZWZhdWx0OmF9dmFyIFFsPXtleHBvcnRzOnt9fSxHbj17fSxLbD17ZXhwb3J0czp7fX0sSj17fTsvKioKICog'
 || 'QGxpY2Vuc2UgUmVhY3QKICogcmVhY3QucHJvZHVjdGlvbi5taW4uanMKICoKICogQ29weXJpZ2h0IChjKSBGYWNlYm9vaywgSW5jLiBhbmQgaXRzIGFmZmls'
 || 'aWF0ZXMuCiAqCiAqIFRoaXMgc291cmNlIGNvZGUgaXMgbGljZW5zZWQgdW5kZXIgdGhlIE1JVCBsaWNlbnNlIGZvdW5kIGluIHRoZQogKiBMSUNFTlNFIGZp'
 || 'bGUgaW4gdGhlIHJvb3QgZGlyZWN0b3J5IG9mIHRoaXMgc291cmNlIHRyZWUuCiAqL3ZhciBibztmdW5jdGlvbiBjYygpe2lmKGJvKXJldHVybiBKO2JvPTE7'
 || 'dmFyIGE9U3ltYm9sLmZvcigicmVhY3QuZWxlbWVudCIpLGM9U3ltYm9sLmZvcigicmVhY3QucG9ydGFsIiksdT1TeW1ib2wuZm9yKCJyZWFjdC5mcmFnbWVu'
 || 'dCIpLGc9U3ltYm9sLmZvcigicmVhY3Quc3RyaWN0X21vZGUiKSxTPVN5bWJvbC5mb3IoInJlYWN0LnByb2ZpbGVyIiksdz1TeW1ib2wuZm9yKCJyZWFjdC5w'
 || 'cm92aWRlciIpLHY9U3ltYm9sLmZvcigicmVhY3QuY29udGV4dCIpLEU9U3ltYm9sLmZvcigicmVhY3QuZm9yd2FyZF9yZWYiKSxfPVN5bWJvbC5mb3IoInJl'
